#include "telemetry/aggregator.hpp"

#include "telemetry/anomaly.hpp"

#include <set>

namespace telemetry {

Summary aggregate(const std::vector<Record>& records, std::uint32_t input_crc32) {
    Summary summary;
    summary.record_count = records.size();
    summary.input_crc32 = input_crc32;
    std::set<std::string> devices;

    for (const auto& record : records) {
        devices.insert(record.device);
        summary.total_energy_kwh += record.energy_kwh;
        summary.total_errors += record.error_count;
        if (record.load_ratio > summary.peak_load.value) {
            summary.peak_load = PeakLoad{record.timestamp, record.device, record.load_ratio};
        }

        auto& region = summary.regions[record.region];
        ++region.records;
        region.temperature_sum += record.temperature_c;
        region.energy_kwh += record.energy_kwh;
        if (is_alert(record)) {
            ++region.alerts;
        }
    }
    summary.unique_devices = devices.size();
    return summary;
}

}  // namespace telemetry
