#include "telemetry/csv_reader.hpp"

#include "telemetry/text.hpp"

#include <fstream>
#include <stdexcept>
#include <string>

namespace telemetry {

std::vector<Record> read_records(const std::filesystem::path& path) {
    std::ifstream input(path);
    if (!input) {
        throw std::runtime_error("unable to open input file: " + path.string());
    }

    std::string line;
    if (!std::getline(input, line)) {
        throw std::runtime_error("input file is empty");
    }
    const std::string expected =
        "timestamp,region,device,category,temperature_c,load_ratio,error_count,energy_kwh";
    if (line != expected) {
        throw std::runtime_error("unexpected CSV header");
    }

    std::vector<Record> records;
    std::size_t line_number = 1;
    while (std::getline(input, line)) {
        ++line_number;
        if (line.empty()) {
            continue;
        }
        const auto fields = split_csv_row(line);
        if (fields.size() != 8) {
            throw std::runtime_error("expected 8 fields at CSV line " + std::to_string(line_number));
        }
        records.push_back(Record{
            fields[0], fields[1], fields[2], fields[3],
            parse_double(fields[4], "temperature", line_number),
            parse_double(fields[5], "load ratio", line_number),
            parse_int(fields[6], "error count", line_number),
            parse_double(fields[7], "energy", line_number),
        });
    }
    if (records.empty()) {
        throw std::runtime_error("input file contains no records");
    }
    return records;
}

}  // namespace telemetry
