#include "telemetry/json_writer.hpp"

#include "telemetry/text.hpp"

#include <filesystem>
#include <fstream>
#include <iomanip>
#include <stdexcept>

namespace telemetry {

void write_summary_json(const Summary& summary, const std::filesystem::path& output) {
    if (!output.parent_path().empty()) {
        std::filesystem::create_directories(output.parent_path());
    }
    std::ofstream out(output);
    if (!out) {
        throw std::runtime_error("unable to create output file: " + output.string());
    }
    out << std::fixed << std::setprecision(2);
    out << "{\n";
    out << "  \"record_count\": " << summary.record_count << ",\n";
    out << "  \"unique_devices\": " << summary.unique_devices << ",\n";
    out << "  \"total_energy_kwh\": " << summary.total_energy_kwh << ",\n";
    out << "  \"total_errors\": " << summary.total_errors << ",\n";
    out << "  \"input_crc32\": \"" << std::hex << std::setw(8) << std::setfill('0')
        << summary.input_crc32 << std::dec << std::setfill(' ') << "\",\n";
    out << "  \"peak_load\": {\"timestamp\": \"" << json_escape(summary.peak_load.timestamp)
        << "\", \"device\": \"" << json_escape(summary.peak_load.device)
        << "\", \"value\": " << summary.peak_load.value << "},\n";
    out << "  \"regions\": [\n";
    std::size_t index = 0;
    for (const auto& [name, region] : summary.regions) {
        const double average = region.temperature_sum / static_cast<double>(region.records);
        out << "    {\"region\": \"" << json_escape(name) << "\", \"records\": " << region.records
            << ", \"avg_temperature_c\": " << average << ", \"energy_kwh\": " << region.energy_kwh
            << ", \"alerts\": " << region.alerts << "}";
        if (++index != summary.regions.size()) {
            out << ',';
        }
        out << '\n';
    }
    out << "  ]\n";
    out << "}\n";
}

}  // namespace telemetry
