#include "telemetry/aggregator.hpp"
#include "telemetry/crc32.h"
#include "telemetry/csv_reader.hpp"
#include "telemetry/json_writer.hpp"

#include <filesystem>
#include <fstream>
#include <iostream>
#include <iterator>
#include <stdexcept>
#include <vector>

namespace {

std::vector<unsigned char> read_bytes(const std::filesystem::path& path) {
    std::ifstream input(path, std::ios::binary);
    if (!input) {
        throw std::runtime_error("unable to open input bytes: " + path.string());
    }
    return {std::istreambuf_iterator<char>(input), std::istreambuf_iterator<char>()};
}

}  // namespace

int main(int argc, char** argv) {
    if (argc != 3) {
        std::cerr << "usage: telemetry_report <input.csv> <output.json>\n";
        return 2;
    }
    try {
        const std::filesystem::path input_path(argv[1]);
        const auto bytes = read_bytes(input_path);
        const auto checksum = telemetry_crc32(bytes.data(), bytes.size());
        const auto records = telemetry::read_records(input_path);
        const auto summary = telemetry::aggregate(records, checksum);
        telemetry::write_summary_json(summary, argv[2]);
        std::cout << "summarized " << records.size() << " records\n";
        return 0;
    } catch (const std::exception& error) {
        std::cerr << "telemetry error: " << error.what() << '\n';
        return 1;
    }
}
