#include "telemetry/text.hpp"

#include <cerrno>
#include <cstdlib>
#include <iomanip>
#include <sstream>
#include <stdexcept>

namespace telemetry {

std::vector<std::string> split_csv_row(std::string_view line) {
    std::vector<std::string> fields;
    std::string current;
    bool quoted = false;
    for (std::size_t i = 0; i < line.size(); ++i) {
        const char ch = line[i];
        if (ch == '"') {
            if (quoted && i + 1 < line.size() && line[i + 1] == '"') {
                current.push_back('"');
                ++i;
            } else {
                quoted = !quoted;
            }
        } else if (ch == ',' && !quoted) {
            fields.push_back(current);
            current.clear();
        } else {
            current.push_back(ch);
        }
    }
    if (quoted) {
        throw std::runtime_error("unterminated quoted CSV field");
    }
    fields.push_back(current);
    return fields;
}

double parse_double(std::string_view value, const char* field, std::size_t line_number) {
    std::string owned(value);
    char* end = nullptr;
    errno = 0;
    const double parsed = std::strtod(owned.c_str(), &end);
    if (errno != 0 || end != owned.c_str() + owned.size()) {
        throw std::runtime_error("invalid " + std::string(field) + " at CSV line " + std::to_string(line_number));
    }
    return parsed;
}

int parse_int(std::string_view value, const char* field, std::size_t line_number) {
    std::string owned(value);
    char* end = nullptr;
    errno = 0;
    const long parsed = std::strtol(owned.c_str(), &end, 10);
    if (errno != 0 || end != owned.c_str() + owned.size()) {
        throw std::runtime_error("invalid " + std::string(field) + " at CSV line " + std::to_string(line_number));
    }
    return static_cast<int>(parsed);
}

std::string json_escape(std::string_view value) {
    std::ostringstream out;
    for (const unsigned char ch : value) {
        switch (ch) {
            case '\\': out << "\\\\"; break;
            case '"': out << "\\\""; break;
            case '\n': out << "\\n"; break;
            case '\r': out << "\\r"; break;
            case '\t': out << "\\t"; break;
            default:
                if (ch < 0x20) {
                    out << "\\u" << std::hex << std::setw(4) << std::setfill('0') << static_cast<int>(ch);
                } else {
                    out << static_cast<char>(ch);
                }
        }
    }
    return out.str();
}

}  // namespace telemetry

