#!/usr/bin/env python3
"""Verify that the native project was built and consumed the full CSV."""

from __future__ import annotations

import csv
import hashlib
import json
import math
import os
from pathlib import Path
import re
import subprocess
import sys
import tempfile
import zlib


ROOT = Path(__file__).resolve().parents[1]
INPUT = ROOT / "data" / "telemetry.csv"
OUTPUT = ROOT / "artifacts" / "summary.json"
INPUT_SHA256 = "2a226a55ca2756045f4d8d897577489a42e49d3d61d8df287a28d357ccea0cbb"
SOURCE_HASHES = {
