    "include/telemetry/text.hpp": "3283dfc7e503f788f489cfb197a07f555d1ed7095f9143fb26b61df572db7164",
    "src/aggregator.cpp": "9a88679107ab2c54422cee1b38957f4644a6890b17dc691100ba1a348bdc89b5",
    "src/anomaly.cpp": "27e739012efe398bd82bafc7e38bf0d0e737d8a2e561740b6aefa19923470b1a",
    "src/crc32.c": "d26b242e98920c3a1ac74e21e2f1a29ce418ff0438d28c931b6b0350c4f6f0e4",
    "src/csv_reader.cpp": "82b496b0b3ca428be067390db89f5832fb6770e4388f3e630d32e5229096d4c1",
    "src/json_writer.cpp": "bfcc73dc96a0c8871079b2350582db2ccb9509e6fea759650ff9bef9e0eeeed0",
    "src/main.cpp": "ad3a3e3812b7dae6fa025c6003a323478d0a394a1c1fa6ab76237bb73a98d10f",
    "src/text.cpp": "e8434a51ac407fce9e39e9d36915f07c9ad2aec63263c21f0d85ac23c5de92bf",
}


def fail(message: str) -> None:
    print(f"FAIL: {message}")
    raise SystemExit(1)


def close(actual: object, expected: float) -> bool:
    return isinstance(actual, (int, float)) and math.isclose(float(actual), expected, abs_tol=0.005)


def verify_sources() -> None:
    for relative, digest in SOURCE_HASHES.items():
        path = ROOT / relative
        if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest() != digest:
            fail(f"native source or build description changed: {relative}")


def expected_summary() -> dict:
    raw = INPUT.read_bytes()
    if hashlib.sha256(raw).hexdigest() != INPUT_SHA256:
        fail("data/telemetry.csv was modified")

    rows = []
    with INPUT.open(newline="", encoding="utf-8") as handle:
        for row in csv.DictReader(handle):
            rows.append(
                {
                    **row,
                    "temperature_c": float(row["temperature_c"]),
                    "load_ratio": float(row["load_ratio"]),
                    "error_count": int(row["error_count"]),
                    "energy_kwh": float(row["energy_kwh"]),
                }
            )
    regions: dict[str, dict] = {}
    for row in rows:
        item = regions.setdefault(row["region"], {"records": 0, "temperatures": 0.0, "energy": 0.0, "alerts": 0})
        item["records"] += 1
        item["temperatures"] += row["temperature_c"]
        item["energy"] += row["energy_kwh"]
        if row["temperature_c"] >= 72.50 or row["load_ratio"] >= 0.90 or row["error_count"] > 0:
            item["alerts"] += 1
    peak = max(rows, key=lambda row: row["load_ratio"])
    return {
        "record_count": len(rows),
        "unique_devices": len({row["device"] for row in rows}),
        "total_energy_kwh": round(sum(row["energy_kwh"] for row in rows), 2),
        "total_errors": sum(row["error_count"] for row in rows),
        "input_crc32": f"{zlib.crc32(raw) & 0xffffffff:08x}",
        "peak_load": {
            "timestamp": peak["timestamp"],
            "device": peak["device"],
            "value": round(peak["load_ratio"], 2),
        },
        "regions": [
            {
                "region": name,
                "records": values["records"],
                "avg_temperature_c": round(values["temperatures"] / values["records"], 2),
                "energy_kwh": round(values["energy"], 2),
                "alerts": values["alerts"],
            }
            for name, values in sorted(regions.items())
        ],
    }


def verify_binary() -> Path:
    candidates = [path for path in (ROOT / "build").rglob("telemetry_report*") if path.is_file()]
    executable = [path for path in candidates if os.access(path, os.X_OK) and path.suffix not in {".o", ".obj"}]
    if not executable:
        fail("no built telemetry_report executable was found under build/")
    native_magic = (b"\x7fELF", b"MZ", b"\xfe\xed\xfa\xce", b"\xfe\xed\xfa\xcf", b"\xce\xfa\xed\xfe", b"\xcf\xfa\xed\xfe")
    executable = [path for path in executable if path.read_bytes()[:4].startswith(native_magic)]
    if not executable:
        fail("telemetry_report is not a native executable")
    return sorted(executable)[0]


def verify_canary(executable: Path) -> None:
    source = (
        "timestamp,region,device,category,temperature_c,load_ratio,error_count,energy_kwh\n"
        "2026-08-01T00:00Z,north,QA-1,pump,72.50,0.20,0,1.25\n"
        "2026-08-01T00:15Z,south,QA-2,fan,40.00,0.90,2,2.50\n"
        "2026-08-01T00:30Z,north,QA-1,pump,50.00,0.50,1,3.75\n"
    )
    with tempfile.TemporaryDirectory(prefix="telemetry-canary-") as temp:
        input_path = Path(temp) / "canary.csv"
        output_path = Path(temp) / "canary.json"
        input_path.write_text(source, encoding="utf-8", newline="")
        proc = subprocess.run(
            [str(executable), str(input_path), str(output_path)],
            cwd=ROOT,
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=20,
        )
        if proc.returncode != 0 or not output_path.is_file():
            fail(f"built executable failed an independent input: {proc.stderr.strip()}")
        try:
            result = json.loads(output_path.read_text(encoding="utf-8"))
        except Exception as exc:
            fail(f"built executable emitted invalid canary JSON: {exc}")
    if result.get("record_count") != 3 or result.get("unique_devices") != 2:
        fail("built executable did not aggregate the independent input")
    if not close(result.get("total_energy_kwh"), 7.50) or result.get("total_errors") != 3:
        fail("built executable produced incorrect independent totals")
    if result.get("input_crc32") != f"{zlib.crc32(source.encode('utf-8')) & 0xffffffff:08x}":
        fail("built executable did not checksum the independent input")
    regions = result.get("regions")
    if not isinstance(regions, list) or [row.get("region") for row in regions] != ["north", "south"]:
        fail("built executable produced incorrect independent region groups")
    if [row.get("alerts") for row in regions] != [2, 1]:
        fail("built executable did not apply alert boundaries to the independent input")


def verify_output() -> None:
    if not OUTPUT.is_file():
        fail("missing artifacts/summary.json")
    text = OUTPUT.read_text(encoding="utf-8")
    try:
        actual = json.loads(text)
    except Exception as exc:
        fail(f"summary is not valid UTF-8 JSON: {exc}")
    expected = expected_summary()

    for field in ("record_count", "unique_devices", "total_errors", "input_crc32"):
        if actual.get(field) != expected[field]:
            fail(f"incorrect {field}: expected {expected[field]!r}, got {actual.get(field)!r}")
    if not close(actual.get("total_energy_kwh"), expected["total_energy_kwh"]):
        fail("incorrect total_energy_kwh")
    if actual.get("peak_load", {}).get("timestamp") != expected["peak_load"]["timestamp"]:
        fail("incorrect peak-load timestamp")
    if actual.get("peak_load", {}).get("device") != expected["peak_load"]["device"]:
        fail("incorrect peak-load device")
    if not close(actual.get("peak_load", {}).get("value"), expected["peak_load"]["value"]):
        fail("incorrect peak-load value")

    regions = actual.get("regions")
    if not isinstance(regions, list) or len(regions) != len(expected["regions"]):
        fail("regions must contain all six regional summaries")
    names = [item.get("region") for item in regions if isinstance(item, dict)]
    if names != sorted(names):
        fail("regions are not sorted lexicographically")
    for got, want in zip(regions, expected["regions"]):
        for field in ("region", "records", "alerts"):
            if got.get(field) != want[field]:
                fail(f"incorrect regional {field} for {want['region']}")
        for field in ("avg_temperature_c", "energy_kwh"):
            if not close(got.get(field), want[field]):
                fail(f"incorrect regional {field} for {want['region']}")

    decimal_fields = re.findall(
        r'"(?:total_energy_kwh|avg_temperature_c|energy_kwh|value)"\s*:\s*(-?\d+\.\d+)', text
    )
    if len(decimal_fields) != 1 + 1 + 2 * len(expected["regions"]):
        fail("all required decimal-valued fields must be emitted as numbers")
    if any(len(value.rsplit(".", 1)[1]) != 2 for value in decimal_fields):
        fail("temperature, energy, and load values must have exactly two decimal places")


def main() -> None:
    verify_sources()
    executable = verify_binary()
    verify_canary(executable)
    verify_output()
    print("PASS: native executable and telemetry summary are complete and accurate")


if __name__ == "__main__":
    main()
